#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_charset() {
        let charset = preset_to_charset("l").unwrap();
        assert_eq!(charset, charset_lowercase_letters());
        let charset = preset_to_charset("u").unwrap();
        assert_eq!(charset, charset_uppercase_letters());
        let charset = preset_to_charset("d").unwrap();
        assert_eq!(charset, charset_digits());
        let charset = preset_to_charset("s").unwrap();
        assert_eq!(charset, charset_symbols());
        let charset = preset_to_charset("h").unwrap();
        assert_eq!(charset, charset_lowercase_hex());
        let charset = preset_to_charset("H").unwrap();
        assert_eq!(charset, charset_uppercase_hex());
    }

    #[test]
    fn test_combined_charsets() {
        let charset = preset_to_charset("lu").unwrap();
        assert_eq!(
            charset,
            [charset_lowercase_letters(), charset_uppercase_letters()].concat()
        );

        let charset = preset_to_charset("lud").unwrap();
        assert_eq!(
            charset,
            [
                charset_lowercase_letters(),
                charset_uppercase_letters(),
                charset_digits(),
            ]
            .concat()
        );
    }

    #[test]
    fn test_charset_from_file() {
        let charset = charset_from_file(&"test-files/file-charset.txt".to_string()).unwrap();
        assert_eq!(
            charset,
            vec![
                'a', '"', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U', '2', '4', '6', '8', '0',
                '*', '#', '$'
            ]
        );
    }

    #[test]
    fn test_invalid_preset_char() {
        let result = preset_to_charset("x");
        assert!(result.is_err());
    }

    #[test]
    fn test_charset_from_choice_deduplicates() {
        // 'h' (hex: 0-9a-f) and 'd' (digits: 0-9) overlap on digits
        let charset = charset_from_choice(&CharsetChoice::Preset("hd".to_string())).unwrap();
        // charset_from_choice sorts and deduplicates
        let mut expected = charset_lowercase_hex();
        expected.extend(charset_digits());
        expected.sort_unstable();
        expected.dedup();
        assert_eq!(charset, expected);
        assert_eq!(charset.len(), 16); // 0-9 + a-f, no duplicates
    }

    #[test]
    fn test_charset_from_nonexistent_file() {
        let result = charset_from_file(&"nonexistent-file.txt".to_string());
        assert!(result.is_err());
    }
}


use crate::finder_errors::FinderError::{ClapMatchError, InvalidZip};
use thiserror::Error;
use zip::result::ZipError;

#[derive(Error, Debug)]
pub enum FinderError {
    #[error("standard I/O error - {e}")]
    StdIoError { e: std::io::Error },
    #[error("Invalid zip file error - {message}")]
    InvalidZip { message: String },
    #[error("CLI argument error - {message:?}")]
    CliArgumentError { message: String },
    #[error("CLI argument error ({e})")]
    ClapError { e: clap::Error },
    #[error("CLI argument match error ({message})")]
    ClapMatchError { message: String },
}

impl FinderError {
    pub const fn invalid_zip_error(message: String) -> Self {
        InvalidZip { message }
    }
}

impl From<std::io::Error> for FinderError {
    fn from(e: std::io::Error) -> Self {
        Self::StdIoError { e }
    }
}

impl From<ZipError> for FinderError {
    fn from(e: ZipError) -> Self {
        InvalidZip {
            message: format!("{e}"),
        }
    }
}

impl From<clap::Error> for FinderError {
    fn from(e: clap::Error) -> Self {
        Self::ClapError { e }
    }
}

impl From<clap::parser::MatchesError> for FinderError {
    fn from(e: clap::parser::MatchesError) -> Self {
        ClapMatchError {
            message: format!("{e}"),
        }
    }
}


