  28: 
  29: struct DictionaryReader {
  30:     reader: BufReader<File>,
  31:     line_buffer: Vec<u8>,
  32: }
  33: 
  34: impl DictionaryReader {
  35:     pub fn new(file_path: PathBuf) -> Self {
  36:         let file = File::open(file_path).expect("Unable to open file");
  37:         let reader = BufReader::new(file);
  38:         Self {
  39:             reader,
  40:             line_buffer: Vec::new(),
  41:         }
  42:     }
  43: }
  44: 
  45: impl Iterator for DictionaryReader {
  46:     type Item = Vec<u8>;
  47: 
  48:     fn next(&mut self) -> Option<Self::Item> {
  49:         loop {
  50:             self.line_buffer.clear();
  51:             let res = self.reader.read_until(b'\n', &mut self.line_buffer);
  52:             match res {
  53:                 Ok(0) => return None,
  54:                 Ok(_) => {
  55:                     // cleanup line endings
  56:                     if self.line_buffer.last() == Some(&b'\n') {
  57:                         self.line_buffer.pop();
  58:                         if self.line_buffer.last() == Some(&b'\r') {
  59:                             self.line_buffer.pop();
  60:                         }
  61:                     }
  62:                     return Some(self.line_buffer.clone());
  63:                 }
  64:                 Err(_) => continue,
  65:             }
  66:         }
  67:     }
  68: }
